mapper.select:
SELECT u.id, u.user_account, u.username, u.telephone, u.email, u.avater, u.sex, u.region, u.create_date, CASE WHEN tu.id IS NOT NULL THEN 1 ELSE 0 END AS checked FROM `user` u LEFT JOIN `tenant_user` tu ON u.id = tu.user_id AND tu.tenant_id = #{tenantId} WHERE EXISTS ( SELECT 1 FROM `company_user` cu WHERE cu.user_id = u.id AND cu.company_id = #{companyId} )
AND ( u.user_account LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.telephone LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') )
LIMIT #{offset}, #{pageSize}

SELECT tu.*, u.username, u.avater, u.email, u.user_account FROM tenant_user tu LEFT JOIN user u ON tu.user_id = u.id WHERE tu.tenant_id = #{tenantId} AND EXISTS ( SELECT 1 FROM tenant_user admin_tu WHERE admin_tu.tenant_id = #{tenantId} AND admin_tu.user_id = #{userId} AND admin_tu.role IN (1, 2) -- 1-租户管理员，2-超级管理员 )
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.user_account LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.telephone LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY tu.join_date DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE tenant_user tu
JOIN tenant_user admin ON admin.tenant_id = #{tenantId}
    AND admin.user_id = #{adminUserId}
    AND admin.role = 2
    AND admin.disabled = 0
SET tu.role = #{role},
    tu.create_by = #{adminUserId}
WHERE tu.tenant_id = #{tenantId}
    AND tu.user_id = #{userId}
    AND tu.disabled = 0

mapper.select:
SELECT COUNT(*)
FROM tenant_user
WHERE tenant_id = #{tenantId, jdbcType=VARCHAR}
AND user_id = #{userId, jdbcType=VARCHAR}
AND role IN (1, 2) 
AND disabled = 0

mapper.delete:
DELETE FROM tenant_user
WHERE tenant_id = #{tenantId, jdbcType=VARCHAR}
AND user_id = #{userId, jdbcType=VARCHAR}
